def icm_me(stacks, i):
    """Expected points for stacks[i] (Malmuth-Harville). O(n^2): cheap enough per decision."""
    s = stacks[i]
    if s <= 0:
        return 0.0
    others = [x for j, x in enumerate(stacks) if j != i and x > 0]
    S = float(s + sum(others))
    ev = PRIZES[0] * s / S
    if not others:
        return ev
    p2 = p3 = 0.0
    third = len(others) > 1
    for a, sa in enumerate(others):
        pa = sa / S
        rest = S - sa
        p2 += pa * s / rest
        if third:
            inner = 0.0
            for b, sb in enumerate(others):
                if b != a:
                    inner += sb / (rest - sb)
            p3 += pa / rest * inner
    ev += PRIZES[1] * p2
    if third:
        ev += PRIZES[2] * p3 * s
    return ev


# The tables above live for the whole game: move them out of the garbage collector's view so its
# pauses (which can land inside a timed decision) have less to scan.
gc.collect()
gc.freeze()


class Profile:
    __slots__ = ("hands", "vpip", "pfr", "shoves", "faced_raise", "fold_raise", "faced_bet", "fold_bet")

    def __init__(self):
        for k in self.__slots__:
            setattr(self, k, 0)


class MyBot:
    def __init__(self, params=None, seed=None):
        self.p = dict(DEFAULT_PARAMS)
        if params:
            self.p.update(params)
        self.rng = random.Random(seed)
        self.prof = {}
        self.errors = 0      # exceptions caught in get_action (each one became a check/fold)
        self._hand = -1      # hand number the caches below belong to
        self._icm = {}       # (stack totals, opponent) -> ICM premium
        self._board = {}     # board tuple -> evaluate(board)
        p = self.p
        # Widest range any unopened decision can use; anything weaker folds immediately.
        self._max_open = min(1.0, (p["open_pct"] + p["open_late_bonus"]) * (1 + max(0.0, p["steal_widen"]) * 0.45))

    # ---------- engine hooks ----------
    def get_action(self, s):
        try:
            if s["hand_number"] != self._hand:
                self._hand = s["hand_number"]
                self._icm.clear()
                self._board.clear()
            return self.preflop(s) if s["street"] == 0 else self.postflop(s)
        except Exception:
            self.errors += 1
            try:
                return self.passive(s)
            except Exception:
                return ("fold",)

    def on_hand_end(self, info):
        gc.collect(0)  # untimed: clear young garbage now rather than mid-decision
        seen, vpip, pfr, shoves = set(), set(), set(), set()
        faced, folded = set(), set()
        raised = False
        post_faced, post_folded = {}, {}
        street_bet = {}
        for street, seat, kind, _amt, allin in info["history"]:
            seen.add(seat)
            if kind in ("sb", "bb"):
                continue
            if street == 0:
                if kind in ("call", "raise"):
                    vpip.add(seat)
                if kind == "raise":
                    pfr.add(seat)
                    if allin:
                        shoves.add(seat)
                if raised and seat not in faced:
                    faced.add(seat)
                    if kind == "fold":
                        folded.add(seat)
                if kind == "raise":
                    raised = True
            else:
                if street_bet.get(street):
                    post_faced[seat] = post_faced.get(seat, 0) + 1
                    post_folded[seat] = post_folded.get(seat, 0) + (kind == "fold")
                if kind == "raise":
                    street_bet[street] = True
        for seat in seen:
            pr = self.prof.get(seat)
            if pr is None:
                pr = self.prof[seat] = Profile()
            pr.hands += 1
            pr.vpip += seat in vpip
            pr.pfr += seat in pfr
            pr.shoves += seat in shoves
            pr.faced_raise += seat in faced
            pr.fold_raise += seat in folded
            pr.faced_bet += post_faced.get(seat, 0)
            pr.fold_bet += post_folded.get(seat, 0)

    # ---------- opponent reads ----------
    def known(self, seat):
        pr = self.prof.get(seat)
        return pr if pr and pr.hands >= self.p["min_samples"] else None

    def raise_range(self, seat, shove):
        """Estimated width (fraction of hands) of this seat's raising / shoving range."""
        pr = self.known(seat)
        if not pr:
            return self.p["default_range"]
        freq = (pr.shoves if shove and pr.shoves else pr.pfr) / pr.hands
        return min(1.0, max(0.02, freq * self.p["range_mult"]))

    def fold_to_raise(self, seat):
        pr = self.prof.get(seat)
        if not pr or pr.faced_raise < 6:
            return 0.5
        return pr.fold_raise / pr.faced_raise

    def fold_to_bet(self, seat):
        pr = self.prof.get(seat)
        return (pr.fold_bet + 1) / (pr.faced_bet + 2) if pr else 0.5

    def is_station(self, seat):
        pr = self.prof.get(seat)
        return bool(pr) and pr.faced_bet >= 8 and pr.fold_bet / pr.faced_bet < 0.2

    # ---------- helpers ----------
    @staticmethod
    def passive(s):
        return ("check",) if s["to_call"] == 0 else ("fold",)

    @staticmethod
    def raise_to(s, target):
        if not s["can_raise"]:
            return ("call",)
        target = int(max(s["min_raise_to"], min(target, s["max_raise_to"])))
        if target >= 0.7 * s["max_raise_to"]:  # don't leave a sliver behind
            target = s["max_raise_to"]
        return ("raise", target)

    @staticmethod
    def last_raiser(s):
        for street, seat, kind, _a, _ai in reversed(s["history"]):
            if street == s["street"] and kind == "raise":
                return seat
        return None

    def aggressor(self, s):
        """Who made the bet I'm facing: from the history if there is one, otherwise the seat with the
        biggest bet in front of it, otherwise the biggest stack (APIs without history still work)."""
        seat = self.last_raiser(s)
        if seat is not None:
            return seat
        me = s["seat"]
        others = [t for t in s["stacks"] if t != me and t not in s["folded"]] or [t for t in s["stacks"] if t != me]
        if not others:
            return None
        return max(others, key=lambda t: (s["bets"].get(t, 0), s["stacks"][t]))

    @staticmethod
    def seats_behind(s):
        acted = {seat for st, seat, k, _a, _ai in s["history"] if st == s["street"] and k not in ("sb", "bb")}
        out = set(s["folded"]) | set(s["allin"])
        return [t for t in s["stacks"] if t != s["seat"] and t not in acted and t not in out]

    def icm_premium(self, s, opp=None):
        """Extra equity (above 0.5) a stack-for-stack flip needs in ICM terms right now."""
        key = (tuple(s["stacks"].values()), opp)
        hit = self._icm.get(key)
        if hit is None:
            hit = self._icm[key] = self._icm_premium(s, opp)
        return hit

    def _icm_premium(self, s, opp):
        seats = list(s["stacks"])
        me = s["seat"]
        if opp is None:
            others = [t for t in seats if t != me]
            if not others:
                return 0.0
            opp = max(others, key=lambda t: s["stacks"][t])
        st = [s["stacks"][t] for t in seats]
        i, j = seats.index(me), seats.index(opp)
        eff = min(st[i], st[j])
        now = icm_me(st, i)
        win, lose = st[:], st[:]
        win[i] += eff
        win[j] -= eff
        lose[i] -= eff
        lose[j] += eff
        ev_win, ev_lose = icm_me(win, i), self.bust_points(s) if lose[i] == 0 else icm_me(lose, i)
        if ev_win <= ev_lose:
            return 0.0
        return max(0.0, (now - ev_lose) / (ev_win - ev_lose) - 0.5)

    @staticmethod
    def bust_points(s):
        place = s["players_left"]
        return PRIZES[place - 1] if place <= len(PRIZES) else 0.0

    def allin_call_ev(self, s, opp, eq):
        """Expected points of calling an all-in-sized bet minus expected points of folding."""
        seats = list(s["stacks"])
        me = s["seat"]
        i, j = seats.index(me), seats.index(opp)
        my_bet, opp_bet = s["bets"][me], s["bets"][opp]
        dead = s["pot"] - my_bet - opp_bet
        base = [s["stacks"][t] - s["bets"][t] for t in seats]  # everyone's chips minus this street's bets
        me_tot, opp_tot = s["stacks"][me], s["stacks"][opp]
        eff = min(me_tot, opp_tot)

        win, lose, fold = base[:], base[:], base[:]
        win[i] = me_tot + eff + dead
        win[j] = opp_tot - eff
        lose[i] = me_tot - eff
        lose[j] = opp_tot + eff + dead
        fold[i] = me_tot - my_bet
        fold[j] = opp_tot + my_bet + dead
        ev_lose = self.bust_points(s) if lose[i] == 0 else icm_me(lose, i)
        ev_call = eq * icm_me(win, i) + (1 - eq) * ev_lose
        ev_fold = self.bust_points(s) if fold[i] == 0 else icm_me(fold, i)
        return ev_call - ev_fold

    def _max_push(self, s):
        p = self.p
        mine = s["stacks"][s["seat"]]
        biggest_other = max((v for t, v in s["stacks"].items() if t != s["seat"]), default=mine)
        eff_bb = min(mine, biggest_other) / s["big_blind"]
        return (p["push_base"] * (p["push_bb"] / max(eff_bb, 1.0)) ** p["push_exp"]
                * p["push_late_mult"] * (1 + max(0.0, p["steal_widen"]) * 0.45))

    # ---------- preflop ----------
    def preflop(self, s):
        p = self.p
        bb = s["big_blind"]
        c1, c2 = s["hole"]
        pct = PCT[c1][c2]
        if s["current_bet"] <= bb and pct > self._max_open and pct > self._max_push(s):
            # Unopened and weaker than the widest open or push range we could use: fold before any other work.
            return self.passive(s)
        key = KEY[c1][c2]
        me = s["seat"]
        mine = s["stacks"][me]
        biggest_other = max((v for t, v in s["stacks"].items() if t != me), default=mine)
        eff_bb = min(mine, biggest_other) / bb
        late = 1.0 - s["players_behind"] / max(1, s["players_left"] - 1)
        to_call = s["to_call"]

        if s["current_bet"] <= bb:  # unopened (maybe limped)
            push = eff_bb <= p["push_bb"]
            if push:
                base = p["push_base"] * (p["push_bb"] / max(eff_bb, 1.0)) ** p["push_exp"]
                pos = 1 + (p["push_late_mult"] - 1) * late
            else:
                base, pos = p["open_pct"] + p["open_late_bonus"] * late, 1.0
            # Steal widening multiplies the range by 1..steal_max and ICM by 0.25..1, so most
            # hands are decided by these bounds without computing either (same decisions, less work).
            lo = base * pos * 0.25 * (1 - 1e-9)
            steal_max = 1 + max(0.0, p["steal_widen"]) * 0.45 * late
            if pct > base * pos * steal_max * (1 + 1e-9):
                return self.passive(s)
            if pct > lo:
                behind = self.seats_behind(s)
                ftr = sum(self.fold_to_raise(t) for t in behind) / len(behind) if behind else 1.0
                steal = 1 + p["steal_widen"] * max(0.0, ftr - 0.55) * late
                rng = base * (pos * steal) if push else base * steal
                if pct > rng:
                    return self.passive(s)
                if pct > rng * 0.25 and pct > rng * max(0.25, 1 - p["icm_k"] * self.icm_premium(s)):
                    return self.passive(s)
            if push:
                return self.raise_to(s, s["max_raise_to"])
            limpers = sum(1 for st, _, k, _a, _ai in s["history"] if st == 0 and k == "call")
            return self.raise_to(s, bb * (p["open_size"] + limpers))

        raiser = self.aggressor(s)
        if raiser is None:
            return self.passive(s)
        if to_call >= 0.4 * s["stack"] or eff_bb <= p["push_bb"]:
            # Committing decision: compare expected points of going all-in vs folding.
            shove = raiser is not None and raiser in s["allin"]
            width = self.raise_range(raiser, shove) if raiser is not None else p["default_range"]
            eq = equity_vs_range(key, width, RANGE_EQ)
            others_in = sum(1 for t in s["stacks"] if t not in (me, raiser) and s["bets"][t] > bb)
            eq = eq ** (1 + 0.8 * others_in)  # crude multiway discount
            if self.allin_call_ev(s, raiser, eq) > p["icm_call_margin"]:
                return self.raise_to(s, s["max_raise_to"])
            return self.passive(s)

        # Normal raise: scale ranges by how wide this raiser opens and by ICM pressure.
        width = self.raise_range(raiser, False) if raiser is not None else p["ref_pfr"]
        looseness = min(2.5, max(0.4, width / (p["ref_pfr"] * p["range_mult"])))
        if pct <= p["threebet_pct"] * looseness:
            return self.raise_to(s, s["current_bet"] * 3)
        call_rng = p["call_raise_pct"] * looseness
        if pct > call_rng:
            return self.passive(s)
        if pct <= call_rng * 0.25 or pct <= call_rng * max(0.25, 1 - p["icm_k"] * self.icm_premium(s, raiser)):
            return ("call",)
        return self.passive(s)

    # ---------- postflop ----------
    def made_strength(self, hole, board):
        v = evaluate(hole + board)
        cat = v >> 20
        bkey = tuple(board)
        bv = self._board.get(bkey)
        if bv is None:
            bv = self._board[bkey] = evaluate(board)
        bcat = bv >> 20
        if cat <= bcat:
            return 0.12  # playing the board
        branks = sorted((c >> 2 for c in board), reverse=True)
        hranks = [c >> 2 for c in hole]
        if cat == PAIR:
            pr = ((v >> 16) & 15) - 1
            if hranks[0] == hranks[1] and pr > branks[0]:
                return 0.72  # overpair
            if pr == branks[0]:
                kicker = max((r for r in hranks if r != pr), default=12)
                return 0.6 if kicker >= 9 else 0.52  # top pair
            return 0.42 if pr >= branks[1] else 0.3
        if cat == TWO_PAIR:
            return 0.5 if bcat == PAIR else 0.78
        if cat == TRIPS:
            return 0.75 if bcat == PAIR else 0.86
        return {STRAIGHT: 0.87, FLUSH: 0.91, FULL_HOUSE: 0.96}.get(cat, 0.99)

    @staticmethod
    def draw_equity(hole, board, street):
        if street == 3:
            return 0.0
        cards = hole + board
        outs = 0.0
        for su in range(4):
            if sum(1 for c in cards if c & 3 == su) == 4 and any(c & 3 == su for c in hole):
                outs += 9
        mask = 0
        for c in cards:
            mask |= 1 << (c >> 2)
        if straight_high(mask) < 0:
            ranks = sum(1 for r in range(13) if not mask >> r & 1 and straight_high(mask | 1 << r) >= 0)
            outs += min(8, 4 * ranks) * (0.7 if outs else 1.0)
        return min(0.6, outs * (0.04 if street == 1 else 0.02))

    def postflop(self, s):
        p = self.p
        hole, board = list(s["hole"]), s["board"]
        me = s["seat"]
        n_opp = max(1, s["active_in_hand"] - 1)
        made = self.made_strength(hole, board) ** (1 + 0.6 * (n_opp - 1))
        draw = self.draw_equity(hole, board, s["street"])
        e = max(made, draw)
        pot, to_call = s["pot"], s["to_call"]
        opps = [t for t in s["stacks"] if t != me and t not in s["folded"]]
        vs_station = n_opp == 1 and self.is_station(opps[0])

        if to_call == 0:
            if e >= p["bet_eq"] - (p["station_value"] if vs_station else 0.0):
                return self.raise_to(s, s["bet"] + p["value_frac"] * pot)
            raised_pre = any(st == 0 and seat == me and k == "raise"
                             for st, seat, k, _a, _ai in s["history"])
            if (raised_pre and n_opp == 1 and not vs_station and s["street"] == 1
                    and self.rng.random() < p["cbet"]):
                return self.raise_to(s, s["bet"] + 0.5 * pot)
            if n_opp == 1 and not vs_station:
                bluff = self.raise_to(s, s["bet"] + p["bluff_frac"] * pot)
                if p["semibluff"] > 0 and draw >= 0.15 and self.rng.random() < p["semibluff"]:
                    return bluff
                if (p["barrel"] > 0 and s["street"] == 2
                        and any(st == 1 and seat == me and k == "raise" for st, seat, k, _a, _ai in s["history"])
                        and self.rng.random() < p["barrel"]):
                    return bluff
                if p["stab_fold"] <= 1.0 and self.fold_to_bet(opps[0]) >= p["stab_fold"]:
                    return bluff
            return ("check",)

        odds = to_call / (pot + to_call)
        if e >= p["raise_eq"]:
            return self.raise_to(s, s["current_bet"] + max(s["big_blind"], p["value_frac"] * (pot + to_call)))
        if (p["semibluff"] > 0 and n_opp == 1 and not vs_station and draw >= 0.15 and s["can_raise"]
                and to_call <= 0.25 * s["stack"] and self.rng.random() < p["semibluff"] * 0.5):
            return self.raise_to(s, s["current_bet"] + max(s["big_blind"], p["bluff_frac"] * (pot + to_call)))
        commit = min(1.0, to_call / max(1, s["stack"]))
        base = odds + p["call_margin"]
        # The ICM premium is between 0 and 0.5, so skip computing it when it can't change the answer.
        if e < base - 1e-12:
            return ("fold",)
        if p["icm_post_k"] >= 0 and e >= base + p["icm_post_k"] * 0.5 * commit + 1e-12:
            return ("call",)
        need = base + p["icm_post_k"] * self.icm_premium(s, self.last_raiser(s)) * commit
        return ("call",) if e >= need else ("fold",)


# ======================= adapter toolkit (adapter.py) =======================
RANKS = "23456789TJQKA"
SUITS = "cdhs"
_SUIT_ALIASES = {"c": 0, "d": 1, "h": 2, "s": 3, "♣": 0, "♦": 1, "♥": 2, "♠": 3,
                 "clubs": 0, "diamonds": 1, "hearts": 2, "spades": 3}
_RANK_ALIASES = {"10": 8, "t": 8, "j": 9, "q": 10, "k": 11, "a": 12, "1": 12}


def parse_rank(r):
    """'A', 'a', '10', 'T', 14, 12 (0-based) ... -> 0..12 (0 = '2', 12 = 'A')."""
    if isinstance(r, int):
        if 2 <= r <= 14:
            return r - 2          # 2..14 convention (most common)
        raise ValueError(f"ambiguous int rank {r}: convert it yourself")
    r = str(r).strip().lower()
    if r in _RANK_ALIASES:
        return _RANK_ALIASES[r]
    if r.isdigit() and 2 <= int(r) <= 9:
        return int(r) - 2
    raise ValueError(f"unknown rank {r!r}")


def parse_suit(x):
    x = str(x).strip().lower()
    if x in _SUIT_ALIASES:
        return _SUIT_ALIASES[x]
    if x[:1] in _SUIT_ALIASES:
        return _SUIT_ALIASES[x[:1]]
    raise ValueError(f"unknown suit {x!r}")


def parse_card(c, int_scheme="rank_major"):
    """Card in almost any format -> our int (rank * 4 + suit).

    Strings: 'Ah', 'AH', 'ah', '10h', 'Th', 'A♥', 'Ace of Hearts'.
    Tuples/lists: ('A', 'h'), (14, 'h'), ('h', 'A') is NOT supported (rank first).
    Dicts: {'rank': 'A', 'suit': 'h'}.
    Ints: int_scheme='rank_major' (rank*4+suit, ours), 'suit_major' (suit*13+rank).
    """
    if isinstance(c, int):
        if int_scheme == "rank_major":
            return c
        if int_scheme == "suit_major":
            return (c % 13) * 4 + c // 13
        raise ValueError("unknown int_scheme")
    if isinstance(c, dict):
        return parse_rank(c.get("rank", c.get("value"))) * 4 + parse_suit(c["suit"])
    if isinstance(c, (tuple, list)):
        return parse_rank(c[0]) * 4 + parse_suit(c[1])
    s = str(c).strip()
    if " of " in s.lower():  # 'Ace of Hearts'
        r, _, su = s.lower().partition(" of ")
        names = {"ace": "a", "king": "k", "queen": "q", "jack": "j", "ten": "10"}
        return parse_rank(names.get(r, r)) * 4 + parse_suit(su)
    return parse_rank(s[:-1]) * 4 + parse_suit(s[-1])


def parse_cards(cs, int_scheme="rank_major"):
    if cs is None:
        return []
    if isinstance(cs, str):  # 'AhKd' or 'Ah Kd' or 'Ah,Kd'
        cs = cs.replace(",", " ").split() if (" " in cs or "," in cs) else [cs[i:i + 2] for i in range(0, len(cs), 2)]
    return [parse_card(c, int_scheme) for c in cs]


def build_state(*, hole, board=(), pot, to_call, stack, big_blind, small_blind=None,
                seat=0, my_bet=0, current_bet=None, min_raise_to=None, max_raise_to=None,
                stacks=None, bets=None, folded=(), allin=(), history=None,
                players_left=None, active_in_hand=None, players_behind=None,
                hand_number=0, button=None, street=None, last_raise_size=None):
    """Full MyBot state from whatever is known. Only the first six arguments are required.

    stack      = MY chips behind (not counting my bet this street)
    my_bet     = my chips already in front of me this street
    stacks     = {seat: chips behind + this street's bet} for everyone dealt in (if known)
    history    = [(street, seat, kind, bet_to_after, is_allin)], kind in sb/bb/fold/check/call/raise
    """
    hole = list(hole)
    board = list(board)
    if street is None:
        street = {0: 0, 3: 1, 4: 2, 5: 3}[len(board)]
    if current_bet is None:
        current_bet = my_bet + to_call
    if max_raise_to is None:
        max_raise_to = my_bet + stack
    if min_raise_to is None:
        min_raise_to = current_bet + max(big_blind, last_raise_size or 0)
    min_raise_to = min(min_raise_to, max_raise_to)
    if stacks is None:
        # Unknown opponents: assume everyone has my stack (neutral for ICM and stack-depth logic).
        n = (players_left or active_in_hand or 2) - 1
        stacks = {seat: stack + my_bet}
        for k in range(1, max(1, n) + 1):
            stacks[seat + k] = stack + my_bet
    stacks = dict(stacks)
    stacks.setdefault(seat, stack + my_bet)
    if bets is None:
        bets = {t: 0 for t in stacks}
        bets[seat] = my_bet
        if current_bet > my_bet:
            # Someone made the bet I'm facing; credit it to an opponent so pot accounting stays right.
            opp = next((t for t in stacks if t != seat and t not in folded), None)
            if opp is not None:
                bets[opp] = current_bet
    bets = {t: bets.get(t, 0) for t in stacks}
    if players_left is None:
        players_left = len(stacks)
    if active_in_hand is None:
        active_in_hand = len(stacks) - len(folded)
    if players_behind is None:
        players_behind = max(0, (active_in_hand - 1) // 2)  # unknown position: assume the middle
    return {
        "seat": seat, "hole": tuple(hole), "board": board, "street": street,
        "pot": pot, "to_call": to_call, "stack": stack, "bet": my_bet,
        "current_bet": current_bet, "min_raise_to": min_raise_to, "max_raise_to": max_raise_to,
        "can_raise": stack > to_call, "small_blind": small_blind or big_blind // 2,
        "big_blind": big_blind, "button": button, "stacks": stacks, "bets": bets,
        "folded": sorted(folded), "allin": sorted(allin), "players_left": players_left,
        "active_in_hand": active_in_hand, "players_behind": players_behind,
        "hand_number": hand_number, "history": list(history or []),
    }


def convert_action(action, state, raise_mode="to"):
    """MyBot action -> (kind, amount) in the contest's convention.

    raise_mode: 'to'  = total bet this street (MyBot's own convention)
                'by'  = increase over the current highest bet
                'add' = chips to put in now (total minus what I already have in front of me)
    """
    kind = action[0]
    if kind != "raise":
        return kind, 0
    to = int(action[1])
    if raise_mode == "to":
        return "raise", to
    if raise_mode == "by":
        return "raise", to - state["current_bet"]
    if raise_mode == "add":
        return "raise", to - state["bet"]
    raise ValueError("raise_mode must be 'to', 'by' or 'add'")


class HandTracker:
    """Gives MyBot a hand counter and end-of-hand callbacks when the API only sends per-decision states.

    A new hand is detected when the hole cards change. If you can collect the hand's action history
    (in MyBot's (street, seat, kind, bet_to, is_allin) format), pass it to `end_hand` so opponent
    tracking works; without it the bot still plays, just without reads on opponents.
    """

    def __init__(self, bot):
        self.bot = bot
        self.hand_number = -1
        self._hole = None
        self.history = []

    def observe(self, hole):
        hole = tuple(sorted(hole))
        if hole != self._hole:
            if self._hole is not None:
                self.end_hand()
            self._hole = hole
            self.hand_number += 1
            self.history = []
        return self.hand_number

    def end_hand(self, history=None, shown=None, stacks=None):
        cb = getattr(self.bot, "on_hand_end", None)
        if cb:
            try:
                cb({"hand_number": self.hand_number, "history": history or self.history,
                    "shown": shown or {}, "board": [], "stacks": stacks or {}})
            except Exception:
                pass


# ======================= CONTEST GLUE: the only part to write on contest day =======================
PARAMS_FILE_CHOICE = "best_params.json"   # which tuned settings were bundled (full / nohistory / minimal)
RAISE_MODE = "to"   # 'to' = total bet, 'by' = increase over current bet, 'add' = chips to put in now

_bot = MyBot(load_tuned(), seed=0)
_tracker = HandTracker(_bot)


def to_state(raw):
    me = raw["you"]
    ids = [p["id"] for p in raw["players"]]
    seat_of = {pid: i for i, pid in enumerate(ids)}
    hole = parse_cards(raw["hole_cards"])
    mine = next(p for p in raw["players"] if p["id"] == me)
    stacks = {seat_of[p["id"]]: p["chips"] + p["bet_this_round"] for p in raw["players"]}
    bets = {seat_of[p["id"]]: p["bet_this_round"] for p in raw["players"]}
    folded = [seat_of[p["id"]] for p in raw["players"] if p["status"] == "folded"]
    allin = [seat_of[p["id"]] for p in raw["players"] if p["status"] == "all_in"]
    current = mine["bet_this_round"] + raw["call_amount"]
    return build_state(
        hole=hole, board=parse_cards(raw["community_cards"]), pot=raw["pot"],
        to_call=raw["call_amount"], stack=mine["chips"], my_bet=mine["bet_this_round"],
        big_blind=raw["big_blind"], small_blind=raw["small_blind"], seat=seat_of[me],
        current_bet=current, min_raise_to=current + raw["min_raise_by"], max_raise_to=current + raw["max_raise_by"],
        stacks=stacks, bets=bets, folded=folded, allin=allin, players_left=len(ids),
        active_in_hand=len(ids) - len(folded), players_behind=len(raw["acting_order"]),
        hand_number=_tracker.observe(hole))


def from_action(action, state):
    kind, amount = convert_action(action, state, "by")
    return {"action": kind, "amount": amount}


def get_action(raw):
    """Contest entry point: rename to whatever the contest calls."""
    state = to_state(raw)
    return from_action(_bot.get_action(state), state)
